import csv
import io
from loans import active

def export_csv(loans):
    stream = io.StringIO(newline="")
    writer = csv.writer(stream)
    writer.writerow(["loan_id", "tool", "due_at"])
    for loan in sorted(active(loans), key=lambda loan: loan["tool"]):
        writer.writerow([loan["loan_id"], loan["tool"], loan["due_at"] or ""])
    return stream.getvalue()
